extend('it-monferrato','producers','Uvalino reference||Uvalino 参考','Cascina Castlet’s Uceline provides a documented Monferrato Rosso example.||Cascina Castlet 的 Uceline 提供有技术资料的 Monferrato Rosso 范例。','https://www.cascinacastlet.com/sites/default/files/uceline-it.pdf')
# Source references for each linked grape are tied to explicit legal/producer evidence.
for rid in ['it-asti','it-barbera-dasti','it-nizza','it-dogliani','it-ovada','it-brachetto-dacqui','it-alta-langa','it-ruche-di-castagnole-monferrato','it-freisa-dasti','it-grignolino-dasti','it-monferrato-doc']:
 r=next(x for x in D['regions'] if x['id']==rid)
 for gg in r['grapes']:
  gg['role']=b('Authorised variety; composition and category are specified above.||获准品种；具体比例及类别见上文。')
# Uvalino is supported by an identified producer dossier rather than inferred permission alone.
r=next(x for x in D['regions'] if x['id']=='it-monferrato-doc')
u='https://www.cascinacastlet.com/sites/default/files/uceline-it.pdf'
r['sources'].append({'id':sid(u),'title':'Cascina Castlet · Uceline','url':u})
next(x for x in r['grapes'] if x['grapeId']=='uvalino').update(sourceIds=[sid(u)],role=b('Uceline producer reference for Monferrato Rosso.||Uceline 提供 Monferrato Rosso 生产者参考。'))
W('it-monferrato-doc','Uceline','Cascina Castlet',u,'Uvalino; exact producer technical sheet.||Uvalino；生产者具体技术资料。')
save()
